    try{$remote=stripe_billing_api_request($config,$settings,'POST','customers/'.rawurlencode((string)$row['stripe_customer_id']).'/balance_transactions',['amount'=>(int)$row['amount_cents'],'currency'=>(string)$row['currency'],'description'=>(string)$row['reason'],'metadata'=>['annotated_credit_adjustment_id'=>(string)$row['public_id'],'annotated_account_id'=>(string)$row['account_id']],(string)$row['idempotency_key']);$remoteId=(string)($remote['id']??'');if($remoteId==='')throw new RuntimeException('Stripe did not return a customer balance transaction ID.');$pdo->prepare("UPDATE commercial_credit_adjustments SET stripe_balance_transaction_id=?,status='applied',last_error=NULL,applied_at=COALESCE(applied_at,NOW()) WHERE id=?")->execute([$remoteId,(int)$row['id']]);return commercial_credit_row($pdo,(string)$row['public_id'])??$row;}catch(Throwable $e){$pdo->prepare("UPDATE commercial_credit_adjustments SET status='failed',last_error=? WHERE id=?")->execute([mb_substr($e->getMessage(),0,1000),(int)$row['id']]);throw $e;}
}
function commercial_credit_adjust(PDO $pdo,array $config,array $admin,string $accountPublicId,string $direction,int $amountCents,string $reason,?int $relatedId=null): array {
    if(($admin['role']??'')!=='admin')throw new RuntimeException('Administrator access required.');if(!commercial_promotions_ready($pdo))throw new RuntimeException('Coupons, Promotions & Credits requires migration 071.');if(!in_array($direction,['credit','debit','reversal'],true))throw new InvalidArgumentException('Invalid credit adjustment type.');if($amountCents<1||$amountCents>10000000)throw new InvalidArgumentException('Credit adjustment must be between $0.01 and $100,000.00.');$reason=trim($reason);if($reason==='')throw new InvalidArgumentException('A reason is required.');
    $account=stripe_billing_account_by_public($pdo,$accountPublicId);if(!$account)throw new RuntimeException('Account not found.');$settings=stripe_billing_settings($pdo);$mode=(string)$settings['mode'];$customer=stripe_billing_customer_ensure($pdo,$config,$account);$signed=$direction==='credit'?-$amountCents:($direction==='debit'?$amountCents:$amountCents);$public=ulid_like();$idem='annotated-credit-'.hash('sha256',$mode.'|'.$public.'|'.$signed);
