      ->execute([$public,(int)$account['id'],$mode,(int)$admin['id'],$direction,$signed,mb_substr($reason,0,500),$idem,(string)$customer['stripe_customer_id'],$relatedId]);$row=commercial_credit_row($pdo,$public);$after=commercial_credit_retry($pdo,$config,$row);commercial_audit($pdo,null,(int)$account['id'],(int)$admin['id'],'credit_adjustment_created',null,$after,'Administrator created Stripe customer credit balance adjustment.');return $after;
}
function commercial_credit_reverse(PDO $pdo,array $config,array $admin,string $publicId,string $reason): array {
    $original=commercial_credit_row($pdo,$publicId);if(!$original||$original['status']!=='applied')throw new RuntimeException('Only applied credit adjustments can be reversed.');$q=$pdo->prepare("SELECT COUNT(*) FROM commercial_credit_adjustments WHERE related_adjustment_id=? AND status IN ('creating','applied')");$q->execute([(int)$original['id']]);if((int)$q->fetchColumn()>0)throw new RuntimeException('This adjustment already has a reversal.');$accountQ=$pdo->prepare('SELECT public_id FROM accounts WHERE id=?');$accountQ->execute([(int)$original['account_id']]);$accountPublic=(string)$accountQ->fetchColumn();$amount=abs((int)$original['amount_cents']);$direction=(int)$original['amount_cents']<0?'debit':'credit';$r=commercial_credit_adjust($pdo,$config,$admin,$accountPublic,$direction,$amount,$reason,(int)$original['id']);$pdo->prepare("UPDATE commercial_credit_adjustments SET adjustment_type='reversal' WHERE id=?")->execute([(int)$r['id']]);return commercial_credit_row($pdo,(string)$r['public_id'])??$r;
}
function commercial_credit_retry_public(PDO $pdo,array $config,array $admin,string $publicId): array {if(($admin['role']??'')!=='admin')throw new RuntimeException('Administrator access required.');$r=commercial_credit_row($pdo,$publicId);if(!$r)throw new RuntimeException('Credit adjustment not found.');return commercial_credit_retry($pdo,$config,$r);}
function commercial_account_benefits_summary(PDO $pdo,int $accountId): array {
    if(!commercial_promotions_ready($pdo))return ['credit_net_cents'=>0,'discount_total_cents'=>0,'recent_redemptions'=>[]];$mode=(string)(stripe_billing_settings($pdo)['mode']??'test');$q=$pdo->prepare("SELECT COALESCE(SUM(amount_cents),0) FROM commercial_credit_adjustments WHERE account_id=? AND stripe_mode=? AND status='applied'");$q->execute([$accountId,$mode]);$credit=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COALESCE(SUM(discount_amount_cents),0) FROM commercial_discount_events WHERE account_id=? AND stripe_mode=?');$q->execute([$accountId,$mode]);$discount=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT r.*,p.code,p.name promotion_name FROM commercial_promotion_redemptions r JOIN commercial_promotions p ON p.id=r.promotion_id WHERE r.account_id=? AND r.stripe_mode=? AND r.status='applied' ORDER BY r.applied_at DESC,r.id DESC LIMIT 5");$q->execute([$accountId,$mode]);return ['credit_net_cents'=>$credit,'discount_total_cents'=>$discount,'recent_redemptions'=>$q->fetchAll()?:[]];
}
function commercial_revenue_adjustment_summary(PDO $pdo,int $days=30): array {
    if(!commercial_promotions_ready($pdo))return ['gross_cents'=>0,'discount_cents'=>0,'net_cents'=>0,'credit_issued_cents'=>0,'debit_issued_cents'=>0];$days=max(1,min(3650,$days));$mode=(string)(stripe_billing_settings($pdo)['mode']??'test');$q=$pdo->prepare("SELECT COALESCE(SUM(gross_subtotal_cents),0) gross,COALESCE(SUM(discount_amount_cents),0) discount,COALESCE(SUM(net_total_cents),0) net FROM commercial_discount_events WHERE stripe_mode=? AND created_at>=DATE_SUB(NOW(),INTERVAL ".$days." DAY)");$q->execute([$mode]);$d=$q->fetch()?:[];$q=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN amount_cents<0 THEN -amount_cents ELSE 0 END),0) credits,COALESCE(SUM(CASE WHEN amount_cents>0 THEN amount_cents ELSE 0 END),0) debits FROM commercial_credit_adjustments WHERE stripe_mode=? AND status='applied' AND created_at>=DATE_SUB(NOW(),INTERVAL ".$days." DAY)");$q->execute([$mode]);$c=$q->fetch()?:[];return ['gross_cents'=>(int)($d['gross']??0),'discount_cents'=>(int)($d['discount']??0),'net_cents'=>(int)($d['net']??0),'credit_issued_cents'=>(int)($c['credits']??0),'debit_issued_cents'=>(int)($c['debits']??0)];
}
function commercial_promotions_list(PDO $pdo): array {return commercial_promotions_ready($pdo)?($pdo->query("SELECT p.*,(SELECT COUNT(*) FROM commercial_promotion_redemptions r WHERE r.promotion_id=p.id AND r.status='applied') applied_redemptions FROM commercial_promotions p ORDER BY FIELD(p.status,'active','draft','archived'),p.updated_at DESC,p.id DESC")->fetchAll()?:[]):[];}
function commercial_recent_redemptions(PDO $pdo,int $limit=100): array {return commercial_promotions_ready($pdo)?($pdo->query("SELECT r.*,p.code,p.name promotion_name,a.public_id account_public_id,a.name account_name,sp.name package_name FROM commercial_promotion_redemptions r JOIN commercial_promotions p ON p.id=r.promotion_id JOIN accounts a ON a.id=r.account_id JOIN subscription_packages sp ON sp.id=r.package_id ORDER BY r.id DESC LIMIT ".max(1,min(500,$limit)))->fetchAll()?:[]):[];}
function commercial_recent_discount_events(PDO $pdo,int $limit=100): array {return commercial_promotions_ready($pdo)?($pdo->query("SELECT d.*,p.code,a.name account_name FROM commercial_discount_events d LEFT JOIN commercial_promotions p ON p.id=d.promotion_id JOIN accounts a ON a.id=d.account_id ORDER BY d.id DESC LIMIT ".max(1,min(500,$limit)))->fetchAll()?:[]):[];}
function commercial_recent_credits(PDO $pdo,int $limit=100): array {return commercial_promotions_ready($pdo)?($pdo->query("SELECT c.*,a.public_id account_public_id,a.name account_name,u.username actor_username FROM commercial_credit_adjustments c JOIN accounts a ON a.id=c.account_id LEFT JOIN users u ON u.id=c.actor_user_id ORDER BY c.id DESC LIMIT ".max(1,min(500,$limit)))->fetchAll()?:[]):[];}
function commercial_promotions_agent_context(PDO $pdo,array $viewer): string {
    if(($viewer['role']??'')!=='admin'||!commercial_promotions_ready($pdo))return '';$mode=(string)(stripe_billing_settings($pdo)['mode']??'test');$q=$pdo->prepare("SELECT COUNT(*) FROM commercial_promotions WHERE status='active' AND (starts_at IS NULL OR starts_at<=NOW()) AND (ends_at IS NULL OR ends_at>=NOW())");$q->execute();$active=(int)$q->fetchColumn();$summary=commercial_revenue_adjustment_summary($pdo,30);$q=$pdo->prepare("SELECT COUNT(*) FROM commercial_promotion_redemptions WHERE stripe_mode=? AND status='applied'");$q->execute([$mode]);$redemptions=(int)$q->fetchColumn();return "Admin promotions and credits context (read-only). Stripe mode: {$mode}. Active promotions: {$active}. Applied redemptions: {$redemptions}. Recorded invoice discounts in the last 30 days: $".number_format($summary['discount_cents']/100,2).". Customer credit adjustments issued in the last 30 days: $".number_format($summary['credit_issued_cents']/100,2).". Annotated commercial policy and audit records are authoritative; Stripe mirrors collection behavior.";
}
